with checks as ( select 'profiles.notify_email' as thing, exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'notify_email') as ok union all select 'notify_email shape check', exists (select 1 from pg_constraint where conname = 'profiles_notify_email_shape') union all select 'anyone can set their own address', exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'profiles' and policyname = 'profiles: update own') union all select 'own update still pins role', coalesce((select with_check like '%role%' from pg_policies where schemaname = 'public' and tablename = 'profiles' and policyname = 'profiles: update own'), false) union all select 'management can set it for others', exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'profiles' and policyname = 'profiles: management update any') union all select 'fn notify_new_version', exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'notify_new_version') union all select 'trigger submission_versions_notify', exists (select 1 from pg_trigger where tgname = 'submission_versions_notify' and not tgisinternal) union all select 'new cut tells the client too', coalesce((select prosrc like '%upload_new_version_client%' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'notify_new_version'), false) union all select 'no duplicate email on the first cut', coalesce((select prosrc like '%new.version > 1%' from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'notify_new_version'), false) ) select thing, case when ok then 'OK' else 'PROBLEM' end as state from checks order by thing; with samples(value) as ( values ('someone@example.co.uk'), ('first.last+crm@example.com'), (null), ('not an email'), ('missing@domain'), ('@example.com'), ('two spaces@example.com') ) select coalesce(value, '(blank - falls back to the login address)') as typed, case when value is null or value ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then 'accepted' else 'rejected' end as result from samples; select role, full_name, coalesce(notify_email, '(login address)') as mail_goes_to from profiles order by role, full_name;
